cJSON * cJSON_CreateTopLevel(const struct TopLevel * x) {
    cJSON * j = NULL;
    if (NULL != x) {
        if (NULL != (j = cJSON_CreateObject())) {
            if (NULL != x->booster) {
                cJSON * j1 = cJSON_AddArrayToObject(j, "booster");
                if (NULL != j1) {
                    enum Booster * x1 = list_get_head(x->booster);
                    while (NULL != x1) {
                        cJSON_AddItemToArray(j1, cJSON_CreateBooster(*x1));
                        x1 = list_get_next(x->booster);
                    }
                }
            }
            if (NULL != x->border) {
                cJSON_AddStringToObject(j, "border", x->border);
            }
            else {
                cJSON_AddStringToObject(j, "border", "");
            }
            if (NULL != x->cards) {
                cJSON * j1 = cJSON_AddArrayToObject(j, "cards");
                if (NULL != j1) {
                    struct Card * x1 = list_get_head(x->cards);
                    while (NULL != x1) {
                        cJSON_AddItemToArray(j1, cJSON_CreateCard(x1));
                        x1 = list_get_next(x->cards);
                    }
                }
            }
            if (NULL != x->code) {
                cJSON_AddStringToObject(j, "code", x->code);
            }
            else {
                cJSON_AddStringToObject(j, "code", "");
            }
            if (NULL != x->gatherer_code) {
                cJSON_AddStringToObject(j, "gathererCode", x->gatherer_code);
            }
            else {
                cJSON_AddStringToObject(j, "gathererCode", "");
            }
            if (NULL != x->magic_cards_info_code) {
                cJSON_AddStringToObject(j, "magicCardsInfoCode", x->magic_cards_info_code);
            }
            else {
                cJSON_AddStringToObject(j, "magicCardsInfoCode", "");
            }
            cJSON_AddNumberToObject(j, "mkm_id", x->mkm_id);
            if (NULL != x->mkm_name) {
                cJSON_AddStringToObject(j, "mkm_name", x->mkm_name);
            }
            else {
                cJSON_AddStringToObject(j, "mkm_name", "");
            }
            if (NULL != x->name) {
                cJSON_AddStringToObject(j, "name", x->name);
            }
            else {
                cJSON_AddStringToObject(j, "name", "");
            }
            if (NULL != x->release_date) {
                cJSON_AddStringToObject(j, "releaseDate", x->release_date);
            }
            else {
                cJSON_AddStringToObject(j, "releaseDate", "");
            }
            if (NULL != x->type) {
                cJSON_AddStringToObject(j, "type", x->type);
            }
            else {
                cJSON_AddStringToObject(j, "type", "");
            }
        }
    }
    return j;
}

char * cJSON_PrintTopLevel(const struct TopLevel * x) {
    char * s = NULL;
    if (NULL != x) {
        cJSON * j = cJSON_CreateTopLevel(x);
        if (NULL != j) {
            s = cJSON_Print(j);
            cJSON_Delete(j);
        }
    }
    return s;
}

void cJSON_DeleteTopLevel(struct TopLevel * x) {
    if (NULL != x) {
        if (NULL != x->booster) {
            enum Booster * x1 = list_get_head(x->booster);
            while (NULL != x1) {
                cJSON_free(x1);
                x1 = list_get_next(x->booster);
            }
            list_release(x->booster);
        }
        if (NULL != x->border) {
            cJSON_free(x->border);
        }
        if (NULL != x->cards) {
            struct Card * x1 = list_get_head(x->cards);
            while (NULL != x1) {
                cJSON_DeleteCard(x1);
                x1 = list_get_next(x->cards);
            }
            list_release(x->cards);
        }
        if (NULL != x->code) {
            cJSON_free(x->code);
        }
        if (NULL != x->gatherer_code) {
            cJSON_free(x->gatherer_code);
        }
        if (NULL != x->magic_cards_info_code) {
            cJSON_free(x->magic_cards_info_code);
        }
        if (NULL != x->mkm_name) {
            cJSON_free(x->mkm_name);
        }
        if (NULL != x->name) {
            cJSON_free(x->name);
        }
        if (NULL != x->release_date) {
            cJSON_free(x->release_date);
        }
        if (NULL != x->type) {
            cJSON_free(x->type);
        }
        cJSON_free(x);
    }
}
